actions.script:
List allAssets = ec.entity.find('mantle.product.asset.Asset').list() Map<String, List> childrenByParent = [:] allAssets.each { a -> String parentId = a.parentAssetId as String if (parentId) childrenByParent.computeIfAbsent(parentId, { [] }).add(a) }
Closure buildNode buildNode = { assetValue -> String assetId = assetValue.assetId as String def deviceValue = ec.entity.find('moqui.device.Device').condition('assetId', assetId).one() List connections = deviceValue ? ec.entity.find('moqui.device.DeviceConnection').condition('deviceId', deviceValue.deviceId).list() : [] List contents = ec.entity.find('mantle.product.asset.AssetContent').condition('assetId', assetId).list() List children = (childrenByParent[assetId] ?: []).collect { buildNode(it) } return [ assetId : assetId, assetName : assetValue.assetName, productId : assetValue.productId, serialNumber : assetValue.serialNumber, statusId : assetValue.statusId, device : deviceValue ? [deviceId: deviceValue.deviceId, deviceTypeEnumId: deviceValue.deviceTypeEnumId] : null, connections : connections.collect { [connectionName: it.connectionName, driverEnumId: it.driverEnumId, transportEnumId: it.transportEnumId] }, content : contents.collect { [assetContentId: it.assetContentId, contentTypeEnumId: it.contentTypeEnumId, contentLocation: it.contentLocation] }, children : children ] }
def topAsset = ec.entity.find('mantle.product.asset.Asset').condition('assetId', topAssetId).one() assets = topAsset ? [buildNode(topAsset)] : []
